def clean(path, ixps):
    result = []
    for x in path:
        if x not in ixps and (not result or x != result[-1]):
            result.append(x)
    return tuple(result)


def topology(data, ixps):
    paths = {}
    for record in data['rib']:
        path = clean(record['path'], ixps)
        if len(path) >= 2 and len(set(path)) == len(path):
            paths[path] = paths.get(path, 0) + record['count']
    rounds = {}
    for path in paths:
        for a, b in zip(path, path[1:]):
            rounds[canonical(a, b)] = 0
    require(len(rounds) <= 4096)
    r = 1
    while paths:
        # A bit for each canonical endpoint survives only if that *same*
        # endpoint is external in every current path containing the link.
        masks = {}
        for path in paths:
            first, last = path[0], path[-1]
            for a, b in zip(path, path[1:]):
                edge = canonical(a, b)
                u, v = edge
                mask = int(u == first or u == last) | (int(v == first or v == last) << 1)
                masks[edge] = masks.get(edge, 3) & mask
        removed = {edge for edge, mask in masks.items() if mask}
        if not removed:
            break
        for edge in removed:
            rounds[edge] = r
        trimmed = {}
        for path, count in paths.items():
            start = int(canonical(path[0], path[1]) in removed)
            end = len(path) - int(canonical(path[-2], path[-1]) in removed)
            if end - start >= 2:
                p = path[start:end]
                trimmed[p] = trimmed.get(p, 0) + count
        paths = trimmed
        r += 1
    return paths, rounds


